const venueInvoices = `-- name: VenueInvoices :many

select i.id, i.venue_id, i.number, i.points, i.months, i.monthly, i.vat_percent, i.total, i.status, i.issued_at, i.paid_at, i.note from venue_invoices i
join venues v on v.id = i.venue_id
join handles h on h.id = v.handle_id
where h.normalized = $1 and h.user_id = $2
order by i.issued_at desc
`

type VenueInvoicesParams struct {
	Handle *string    `json:"handle"`
	UserID *uuid.UUID `json:"user_id"`
}

// Hisob-fakturalar -----------------------------------------------------------
func (q *Queries) VenueInvoices(ctx context.Context, arg VenueInvoicesParams) ([]VenueInvoice, error) {
	rows, err := q.db.Query(ctx, venueInvoices, arg.Handle, arg.UserID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VenueInvoice{}
	for rows.Next() {
		var i VenueInvoice
		if err := rows.Scan(
			&i.ID,
			&i.VenueID,
			&i.Number,
			&i.Points,
			&i.Months,
			&i.Monthly,
			&i.VatPercent,
			&i.Total,
			&i.Status,
			&i.IssuedAt,
			&i.PaidAt,
			&i.Note,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

