const venueRequests = `-- name: VenueRequests :many
select r.id, r.venue_id, r.point, r.kind, r.rating, r.note, r.status, r.created_at, r.done_at, r.ip from venue_requests r
join venues v on v.id = r.venue_id
join handles h on h.id = v.handle_id
where h.normalized = $1 and h.user_id = $2
  and ($3::text is null or r.status = $3::text)
order by r.created_at desc
limit $4::int
`

type VenueRequestsParams struct {
	Handle   *string    `json:"handle"`
	UserID   *uuid.UUID `json:"user_id"`
	Status   *string    `json:"status"`
	PageSize int32      `json:"page_size"`
}

func (q *Queries) VenueRequests(ctx context.Context, arg VenueRequestsParams) ([]VenueRequest, error) {
	rows, err := q.db.Query(ctx, venueRequests,
		arg.Handle,
		arg.UserID,
		arg.Status,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []VenueRequest{}
	for rows.Next() {
		var i VenueRequest
		if err := rows.Scan(
			&i.ID,
			&i.VenueID,
			&i.Point,
			&i.Kind,
			&i.Rating,
			&i.Note,
			&i.Status,
			&i.CreatedAt,
			&i.DoneAt,
			&i.Ip,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
